import { createHash, createHmac } from "node:crypto";

/**
 * Byte-identical port of `services/voucher/internal/merchantauth/signing.go`
 * (`Sign`/`compute`). Every merchant integration signs with this file, so a
 * drift here is a drift against a live brand's till — this is why
 * `signing.test.ts` hard-codes vectors generated by calling the REAL Go
 * `Sign`/`Verify` functions from a scratch program outside this repo,
 * rather than only asserting this file agrees with itself.
 *
 * Canonical string (see signing.go's `compute`), newline-joined so no field
 * can contain the separator:
 *   unix-seconds \n key-id \n METHOD \n path-and-query \n idempotency-key \n base64(sha256(body))
 *
 * Header: `t=<unix>,k=<key id>,v1=<hex hmac-sha256>` — the same
 * `X-YourTal-Signature` header shape `Parse`/`Verify` read on the Go side.
 */
export const SIGNATURE_HEADER = "X-YourTal-Signature";

/** Matches `merchantauth.IdempotencyHeader` — signed, so a replay cannot swap it. */
export const IDEMPOTENCY_HEADER = "Idempotency-Key";

export interface SignRequestInput {
  /** The merchant's shared secret. A `string` is treated as its UTF-8 bytes, exactly like Go's `[]byte(secret)`. */
  secret: string | Uint8Array;
  keyId: string;
  method: string;
  /** The request path plus its query string, exactly as sent — never re-derived from a URL object. */
  pathAndQuery: string;
  /** `""` when the call carries no Idempotency-Key. */
  idempotencyKey: string;
  /** The exact bytes that will be sent as the request body. A `string` is hashed as UTF-8. */
  body: string | Uint8Array;
  /** Signed to the second, like Go's `time.Time.Unix()` — sub-second precision is dropped on both sides. */
  timestamp: Date;
}

function toBytes(value: string | Uint8Array): Uint8Array {
  return typeof value === "string" ? new TextEncoder().encode(value) : value;
}

function canonicalString(input: {
  keyId: string;
  method: string;
  pathAndQuery: string;
  idempotencyKey: string;
  body: string | Uint8Array;
  unixSeconds: number;
}): string {
  const bodyDigestBase64 = createHash("sha256").update(toBytes(input.body)).digest("base64");
  return [
    String(input.unixSeconds),
    input.keyId,
    input.method.toUpperCase(),
    input.pathAndQuery,
    input.idempotencyKey,
    bodyDigestBase64,
  ].join("\n");
}

/** Produces the `X-YourTal-Signature` header value for one request. */
export function signRequest(input: SignRequestInput): string {
  const unixSeconds = Math.floor(input.timestamp.getTime() / 1000);
  const canonical = canonicalString({
    keyId: input.keyId,
    method: input.method,
    pathAndQuery: input.pathAndQuery,
    idempotencyKey: input.idempotencyKey,
    body: input.body,
    unixSeconds,
  });
  const mac = createHmac("sha256", toBytes(input.secret)).update(canonical, "utf8").digest("hex");
  return `t=${unixSeconds},k=${input.keyId},v1=${mac}`;
}
